#!/bin/bash
# ICE-table meta learners, final design (pilot 2026-11-20): the SAME experiment twice, only the observations differ.
#   Table 1 OSSE (first): observations generated by F1 (our knowledge model; src/make_osse_obs.py, prefix l63v2osse).
#                         The meta learners are TRAINED here (train ICs, best epoch on val) -> test / test_ood.
#   Table 2 OSE (second): observations of the real system E1 (L63 rho 28, prefix l63v2). The OSSE-trained learners
#                         are applied FROZEN (no retraining): does the method work in the real world?
# Usage: bash src/scripts/ice_meta_v2.sh <osse|ose> <cell c1|c2|c3|c4> <model f1|emulator> <constraint> <seed>
# Records tmp/results/ice_{osse,ose}_meta_<model>/, learners tmp/meta/ice_osse_meta_<model>/, logs tmp/logs/ice/.
# Teacher (cells 1 / 2, training only) = strong-Wolfe L-BFGS, lr 1, budget 150; teacher-pair cache per data set
# tmp/meta/ice_osse_<model>/pairs_<constraint> (cell 2 reuses the one cell 1 seed 0 writes: run c1 s0 first).
cd "$(dirname "$0")/../.."
export OMP_NUM_THREADS=1 MKL_NUM_THREADS=1
P=/Odyssey/private/j25lee/miniforge3/envs/oceanai/bin/python
MODE=$1; C=$2; M=$3; CON=$4; S=$5
PC=tmp/meta/ice_osse_${M}/pairs_${CON}
case $C in
  # cell 1 = supervised learned optimizer (delta_exact): L-BFGS memory input, output relative to the two-loop
  # direction, two-step target, online training, log loss / selection, backtrack safeguard at inference
  c1) X="variant=delta_exact delta_exact.hist_m=10 delta_exact.base=lbfgs delta_exact.first_step=teacher \
delta_exact.hidden=32 delta_exact.batch_size=64 delta_exact.horizon=2 delta_exact.train_loss=logmean \
delta_exact.select=logmean delta_exact.train_mode=online delta_exact.online_cases=100 delta_exact.epochs=30 \
delta_exact.safeguard=backtrack delta_exact.seed=$S delta_exact.pairs_cache=$PC";;
  # cell 2 = unsupervised learned optimizer (delta free): same learner as cell 1, trained on its own trajectory by the
  # first-order decrease of J (l_perf, converged cases masked) + small align to the teacher step + L2
  c2) X="variant=delta delta.output=free net.hidden=32 delta.hist_m=10 delta.base=lbfgs delta.first_step=teacher \
delta.safeguard=backtrack delta.w_perf_delta=2.5 delta.w_align=0.1 delta.meta_lr=1e-3 delta.n_epochs=10 \
delta.batch=100 delta.episode_iters=20 delta.select_epoch=true delta.select_k=10 delta.select_n_val=200 \
delta.train_seed=$S delta.pairs_cache=$PC";;
  # cell 3 = learned optimization (Meta-A unroll, K 20): L-BFGS direction of its own moves + learned correction,
  # backtrack safeguard (reject + halve moves whose J rose), loss mean_m J(x^m) / J(x^0)
  c3) X="variant=unroll unroll.K=20 unroll.base=lbfgs unroll.safeguard=backtrack unroll.loss=sum unroll.use_grad=true \
unroll.epochs=30 unroll.n_val=200 unroll.seed=$S";;
  # cell 4 = adjoint-free learned gradient (8a, supervised by the rho275 emulator's one-interval Jacobians) driving
  # strong-Wolfe L-BFGS; cost in forward runs
  c4) X="variant=learned_grad learned_grad.arch=adjoint learned_grad.data=sampled learned_grad.loss=jacobian \
learned_grad.traj_stride=0 learned_grad.surrogate_emulator=rho275 learned_grad.n_val_ic=200 learned_grad.seed=$S \
diag_true_grad=false";;
  *) echo "unknown cell $C"; exit 1;;
esac
EMU=""; [ "$M" = emulator ] && EMU="emulator=rho275"
NAME=${C}_${CON}_s$S
CKDIR=tmp/meta/ice_osse_meta_$M
COMMON="dataset=v2 model=$M $EMU constraint=$CON pattern=x_only problem=bice method=lbfgs_wolfe lr=1 max_iter=150 \
tol=1e-6 train.n_train=null train.n_val_pairs_ic=200 n_cases=null tag=_$NAME"
mkdir -p tmp/logs/ice tmp/meta/ice_osse_$M $CKDIR
case $MODE in
  osse)   # train on the OSSE train split (best epoch on OSSE val) -> test record + learner, then frozen test_ood
    G=ice_osse_meta_$M
    $P src/run_meta_b.py $COMMON $X data_prefix=l63v2osse result_group=$G ckpt_dir=$CKDIR split=test \
      hydra.run.dir=tmp/hydra/ice/${G}_${NAME}_test > tmp/logs/ice/${G}_${NAME}_test.log 2>&1 || exit 1
    CK=$(ls $CKDIR/*_${CON}_x_only_lbfgs_wolfe_lr1_${NAME}.pt | head -1)
    $P src/run_meta_b.py $COMMON $X data_prefix=l63v2osse result_group=$G checkpoint=$CK split=test_ood \
      hydra.run.dir=tmp/hydra/ice/${G}_${NAME}_test_ood > tmp/logs/ice/${G}_${NAME}_test_ood.log 2>&1 || exit 1;;
  ose)    # the OSSE-trained learner, frozen, on the real-system observations
    G=ice_ose_meta_$M
    CK=$(ls $CKDIR/*_${CON}_x_only_lbfgs_wolfe_lr1_${NAME}.pt | head -1)
    for SP in test test_ood; do
      $P src/run_meta_b.py $COMMON $X data_prefix=l63v2 result_group=$G checkpoint=$CK split=$SP \
        hydra.run.dir=tmp/hydra/ice/${G}_${NAME}_$SP > tmp/logs/ice/${G}_${NAME}_$SP.log 2>&1 || exit 1
    done;;
  *) echo "unknown mode $MODE (osse | ose)"; exit 1;;
esac
